function res = MtrxExp(dt)% Usange : exp for sym matrix% dt: n x n x m, dt = dt'%  [n, n1, m] = size(dt);% %  if ( AreAllSym(dt) == 0 )%|| dt' ~= dtn ~= n1%      help Sym2Vct;%      return%  end%  res = zeros(n,n,m); %for i = 1:mTemp = (dt+dt')/2;[V,S] = eig(Temp);D = sqrt(diag(V'*V));iD = 1./D;V = V*diag(iD);%     [V, S, U] = svd(Temp);%      [V, S, U] = svd(squeeze(dt(:,:,i)));res = real(V*diag(exp(diag(S)))*V'); %end